    /// The parameters, in position order, and how many are required.
    pub(crate) fn layout(self) -> Layout {
        match self {
            Self::If | Self::Probability => Layout {
                params: &["input", "condition", "model", "on_error"],
                required: 2,
            },
            Self::Classify => Layout {
                params: &["input", "labels", "instructions", "model", "on_error"],
                required: 2,
            },
            Self::Score => Layout {
                params: &["input", "instructions", "levels", "model", "on_error"],
                required: 3,
            },
            Self::Decide => Layout {
                params: &["input", "questions", "model", "on_error"],
                required: 2,
            },
        }
    }

    /// The usage line shown in argument errors.
    pub(crate) fn usage(self) -> &'static str {
        match self {
            Self::If => "ai_if(input, condition[, model => 'name'][, on_error => 'fail' | 'null'])",
            Self::Probability => {
                "ai_probability(input, condition[, model => 'name'][, on_error => 'fail' | 'null'])"
            }
            Self::Classify => {
                "ai_classify(input, labels[, instructions => '...'][, model => 'name'][, on_error => 'fail' | 'null'])"
            }
            Self::Score => {
                "ai_score(input, instructions, levels[, model => 'name'][, on_error => 'fail' | 'null'])"
            }
            Self::Decide => {
                "ai_decide(input, questions[, model => 'name'][, on_error => 'fail' | 'null'])"
            }
        }
    }

    /// The SQL type a typed function returns. `ai_decide`'s struct depends on its
    /// questions, so it has none here.
    pub(crate) fn typed_return(self) -> Option<DataType> {
        match self {
            Self::If => Some(DataType::Boolean),
            Self::Probability | Self::Score => Some(DataType::Float64),
            Self::Classify => Some(DataType::Utf8),
            Self::Decide => None,
        }
    }
}

//! The SQL values decision functions return.
//!
//! `ai_decide` returns a struct with one field per question id:
//!
//! - `noul` → `{probability}`
//! - `choice` → `{choice, probabilities: [{value, probability}], confidence}`
//! - `score` → `{score, probabilities: [{value, label, probability}], confidence}`
//!
//! The typed functions return the one value they ask for.

use std::collections::BTreeMap;
use std::sync::Arc;

use arrow::array::{ArrayRef, BooleanArray, Float64Array, StringArray};
use arrow::datatypes::{DataType, Field, Fields, Schema};
use datafusion::common::{DataFusionError, Result, exec_err, internal_err};
use evaluate_api::{Answer, EntryType, NonNullEntry, Question};
use serde_json::{Map, Value, json};

use crate::args::TYPED_QUESTION_ID;
use crate::exec::RowAnswers;
use crate::functions::Kind;

/// The struct field names, shared by the planner's field accesses.
pub(crate) const PROBABILITY: &str = "probability";
pub(crate) const CHOICE: &str = "choice";
pub(crate) const SCORE: &str = "score";
const PROBABILITIES: &str = "probabilities";
const CONFIDENCE: &str = "confidence";
const VALUE: &str = "value";
const LABEL: &str = "label";

/// The threshold above which `ai_if` is true: yes is more likely than no.
pub(crate) const IF_THRESHOLD: f64 = 0.5;

fn float(name: &str) -> Field {
    Field::new(name, DataType::Float64, true)
}

fn list_of(fields: Vec<Field>) -> DataType {
    DataType::List(Arc::new(Field::new_list_field(
        DataType::Struct(Fields::from(fields)),
        true,
    )))
}

/// The struct one question's answer has.
fn answer_type(question: &Question) -> DataType {
    let fields = match question {
        Question::Noul { .. } => vec![float(PROBABILITY)],
        Question::Choice { .. } => vec![
            Field::new(CHOICE, DataType::Utf8, true),
            Field::new(
                PROBABILITIES,
                list_of(vec![
                    Field::new(VALUE, DataType::Utf8, true),
                    float(PROBABILITY),
                ]),
                true,
            ),
            float(CONFIDENCE),
        ],
        Question::Score { .. } => vec![
            float(SCORE),
            Field::new(
                PROBABILITIES,
                list_of(vec![
                    Field::new(VALUE, DataType::Int64, true),
                    Field::new(LABEL, DataType::Utf8, true),
                    float(PROBABILITY),
                ]),
                true,
            ),
            float(CONFIDENCE),
        ],
    };
    DataType::Struct(Fields::from(fields))
}

/// The struct `ai_decide` returns for `questions`.
pub(crate) fn decision_type(questions: &BTreeMap<String, Question>) -> DataType {
    DataType::Struct(Fields::from(
        questions
            .iter()
            .map(|(id, question)| Field::new(id, answer_type(question), true))
            .collect::<Vec<_>>(),
    ))
}
